function integrationEscape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function integrationCards(){return integrationGroups.map((g,i)=>`<section class="card"><span class="num">${g.number} / BO‘LIM</span><h3>${integrationEscape(g.name)}</h3><p class="muted">${g.hours} soat · ${g.topics.length} para · ${g.topics[0].number}–${g.topics.at(-1).number}-mavzular</p><button onclick="showIntegrationPart(${i})">Mavzularni ko‘rish →</button></section>`).join('');}
function integrationDownloads(){return '<div class="downloads"><a href="materials/m8-integration-ish-reja.docx" download>Ish reja — Word ↓</a><a href="materials/m8-integration-konspektlar.zip" download>45 ta konspekt — ZIP ↓</a><a href="materials/m8-integration-loyiha.zip" download>Yakuniy loyiha va testlar — ZIP ↓</a></div>';}
function installIntegrationModule(){
 document.getElementById('modules').insertAdjacentHTML('beforeend',`<details id="m8"><summary>8-modul <span class="muted">· 90 soat</span></summary><div class="lessons"><p class="muted">${integrationEscape(integrationPlan.name)}</p><button class="nav" onclick="showIntegrationOverview()">Modul rejasi →</button>${integrationGroups.map((g,i)=>`<details id="m8g${i}"><summary style="font-size:13px">${g.number}-bo‘lim. ${integrationEscape(g.name)}<br><span class="muted">${g.hours} soat · ${g.topics.length} para</span></summary><div class="lessons">${g.topics.map(t=>`<button class="nav lesson" id="m8l${t.number}" onclick="showIntegrationLesson(${t.number})">${t.number}. ${integrationEscape(t.title)}</button>`).join('')}</div></details>`).join('')}</div></details>`);
 const previousHome=showHome;
 showHome=function(){previousHome();document.getElementById('content').insertAdjacentHTML('beforeend',`<section class="integration-overview"><p class="eyebrow">8-MODUL</p><h2>${integrationEscape(integrationPlan.name)}</h2><p class="muted">90 soat · 45 para · 5 bo‘lim · 20 nazariy va 25 amaliy dars</p><p>Frontend, API va bazani bog‘lashdan avtomatik test, reliz, joriy etish, kuzatish va tiklashgacha. Nazariy tushuntirishdan keyin amaliy ish bajariladi.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${integrationCards()}</div><button class="cta" onclick="showIntegrationOverview()">Integratsiya modulini ochish →</button></section>`);};
}
function showIntegrationOverview(){
 select('home');currentModule=8;document.getElementById('m8').open=true;document.getElementById('crumb').textContent='8-modul / Integratsiya / Ish reja';
 document.getElementById('content').innerHTML=`<button class="back" onclick="showHome()">← Bosh sahifa</button><p class="eyebrow">8-MODUL / ISH REJA</p><h1 style="font-size:36px">${integrationEscape(integrationPlan.name)}</h1><p class="muted">90 soat · 45 para · 40 soat nazariy · 50 soat amaliy</p><p>Node.js 24 · HTTP API · SQLite · node:test. Tayanch: 5–7-modullardagi frontend, backend, SQL va Git.</p>${integrationDownloads()}<p class="notice">Bu siz uchun tuzilgan tavsiya etiladigan mualliflik ish rejasi. Rasmiy tasdiqlangan dastur deb belgilanmagan. 20 ta nazariy darsdan keyin tegishli amaliyot keladi; har bo‘lim oxirida yana bir umumlashtiruvchi loyiha ishi bor.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${integrationCards()}</div><h2>Har bir darsda</h2><p>Konspekt va Word fayli, konspekt asosidagi 15 ta slayd, 10 ta javobli savol, 10 ta test. Mos video topilgan mavzuda video birinchi bo‘limda ochiladi. Amaliy darsda kod yoki hisobot maydoni, tekshirish mezonlari va namuna beriladi.</p><p>Test o‘tish chegarasi 60%. Kam natijada qayta o‘qish tugmasi, yetarli natijada keyingi mavzuga o‘tish tugmasi chiqadi. Amaliy ishni o‘qituvchi alohida tekshiradi.</p><h2>Yakuniy loyiha</h2><p>Vazifalar ilovasi: frontend, HTTP API, SQLite, avtomatik testlar, smoke, offline backup va tiklash. Sof JavaScript mashqlarida platformada ▶ Run mavjud. Server, CI, Docker va hosting amaliyotlari lokal loyiha va yo‘riqnoma asosida bajariladi. Demo login ishlatmaydi; faqat o‘quv ma’lumotlari uchun. Ishlayotgan SQLite bazasidan oddiy copy bilan backup olinmaydi: kursdagi skript avval xizmatni to‘xtatishni talab qiladi.</p>`;
}
function showIntegrationPart(i){
 const g=integrationGroups[i];if(!g)return;select('home');currentModule=8;document.getElementById('m8').open=true;document.getElementById('m8g'+i).open=true;document.getElementById('crumb').textContent=`8-modul / ${g.number}-bo‘lim`;
 document.getElementById('content').innerHTML=`<button class="back" onclick="showIntegrationOverview()">← Modul rejasi</button><p class="eyebrow">8-MODUL / ${g.number}-BO‘LIM</p><h1 style="font-size:34px">${integrationEscape(g.name)}</h1><p class="muted">${g.hours} soat · ${g.topics.length} para</p>${g.topics.map(t=>`<section class="card" style="margin:12px 0"><span class="num">${t.number}-MAVZU · 2 SOAT · ${integrationEscape(t.kind)}</span><h3>${integrationEscape(t.title)}</h3><p>${integrationEscape(t.outcome)}</p><button onclick="showIntegrationLesson(${t.number})">Darsni ochish →</button></section>`).join('')}`;
}
function showIntegrationLesson(n){
 const t=integrationData[n];if(!t)return;const i=integrationGroups.findIndex(g=>g.topics.some(x=>x.number===n)),g=integrationGroups[i];select('m8l'+n);currentModule=8;currentLesson=n;slideIndex=0;document.getElementById('m8').open=true;document.getElementById('m8g'+i).open=true;
 document.getElementById('crumb').textContent=`8-modul / ${g.number}-bo‘lim / ${n}-mavzu`;
 document.getElementById('content').innerHTML=`<button class="back" onclick="showIntegrationPart(${i})">← Bo‘lim mavzulari</button><p class="eyebrow">8-MODUL · ${g.number}-BO‘LIM · ${n}-MAVZU</p><h1 style="font-size:34px">${integrationEscape(t.title)}</h1><p class="muted">2 soat · 1 para · ${integrationEscape(t.kind)}</p><article class="article"><div class="resource-tabs" role="tablist" aria-label="Mavzu materiallari"></div>${[0,1,2,3].map(j=>`<section id="panel${j}" role="tabpanel" aria-labelledby="tab${j}" hidden></section>`).join('')}</article><div style="display:flex;justify-content:space-between;gap:15px;margin-top:24px">${n>1?`<button class="back" onclick="showIntegrationLesson(${n-1})">← Oldingi mavzu</button>`:'<span></span>'}${n<45?`<button class="back" onclick="showIntegrationLesson(${n+1})">Keyingi mavzu →</button>`:'<button class="back" onclick="showIntegrationOverview()">Modul rejasiga qaytish →</button>'}</div>`;
 renderResources(t);
}
